corporate_design.toad_component_blueprint:
canvas {
  size: 920px 560px;
  fill: #0F172A;
  font-family: "Inter, sans-serif";
}

>voltYellow = #EAB308;
>cableBlue = #1D4ED8;
>white = #FFFFFF;

rect #panelCard {
  at: center of canvas;
  size: 840px 460px;
  fill: #1E293B;
  stroke: >voltYellow;
  stroke-width: 1px;
  radius: 8px;
}

text #voltHeader {
  at: top left of #panelCard offset 32px 32px;
  content: "VOLTMEISTER // SCHALTANLAGENBAU • VDE 0100";
  font-size: 14px;
  font-weight: 700;
  color: >voltYellow;
}

text #powerHero {
  at: below #voltHeader offset 16px;
  content: "Mittelspannung & Gewerbe-Photovoltaik";
  font-size: 32px;
  font-weight: 700;
  color: >white;
}
